document.addEventListener('DOMContentLoaded', function() {
    const candidateId = getUrlParameter('id');

    if (candidateId) {
        loadCandidateProfile(candidateId);
    }

    loadAllCandidates();
});

function loadCandidateProfile(candidateId) {
    const container = document.getElementById('candidate-profile');
    const candidate = data.teamMembers.find(member => member.id === candidateId);

    if (!container || !candidate) return;

    container.innerHTML = `
        <div class="card p-8 rounded-lg shadow-sm">
            <div class="grid md:grid-cols-3 gap-8">
                <div class="text-center">
                    <img src="${candidate.image}" alt="${candidate.name}" class="w-48 h-48 rounded-full mx-auto mb-4 object-cover">
                    <h1 class="text-3xl font-bold mb-2">${candidate.name}</h1>
                    <p class="text-xl text-muted mb-4">${candidate.position}</p>
                    <div class="flex flex-wrap gap-2 justify-center">
                        ${candidate.skills.map(skill => `
                            <span class="px-3 py-1 bg-blue-100 text-blue-800 rounded-full text-sm">${skill}</span>
                        `).join('')}
                    </div>
                </div>
                <div class="md:col-span-2">
                    <h2 class="text-2xl font-semibold mb-4">About</h2>
                    <p class="text-muted mb-6">${candidate.bio}</p>

                    <div class="grid md:grid-cols-2 gap-6">
                        <div>
                            <h3 class="text-lg font-semibold mb-2">Experience</h3>
                            <p class="text-muted">${candidate.experience}</p>
                        </div>
                        <div>
                            <h3 class="text-lg font-semibold mb-2">Education</h3>
                            <p class="text-muted">${candidate.education}</p>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    `;
}

function loadAllCandidates() {
    const container = document.getElementById('all-candidates');
    if (!container) return;

    container.innerHTML = data.teamMembers.map(member => `
        <div class="card p-6 rounded-lg shadow-sm text-center">
            <img src="${member.image}" alt="${member.name}" class="w-24 h-24 rounded-full mx-auto mb-4 object-cover">
            <h3 class="text-xl font-semibold mb-2">${member.name}</h3>
            <p class="text-muted mb-4">${member.position}</p>
            <p class="text-sm text-muted mb-4">${member.bio}</p>
            <a href="candidate-information.html?id=${member.id}" class="text-blue-600 hover:underline">View Full Profile</a>
        </div>
    `).join('');
}

